    android.content.SharedPreferences prefs;
    int red=Color.rgb(255,59,69), green=Color.rgb(70,214,155), bg=Color.rgb(5,7,11), panel=Color.rgb(17,21,29), muted=Color.rgb(143,152,168), white=Color.rgb(245,247,250);
